types-prim-001.example:
```js
const kinds = ['hi', 42, 10n, true, undefined, Symbol('id'), null];
console.log(kinds.map(v => typeof v));
// ['string','number','bigint','boolean','undefined','symbol','object']
// note: typeof null is 'object' (a bug) but null is still a primitive
console.log(typeof [], typeof {}, typeof function () {}); // object object function (non-primitives)
```

types-prim-005.example:
```js
let a = 10;
let b = a;  // b gets a COPY of the value 10
b = 20;     // rebinds b only
console.log(a, b); // 10 20 — a is untouched

// contrast: objects share a reference
let o1 = { n: 10 };
let o2 = o1;
o2.n = 20;
console.log(o1.n); // 20 — same object
```

types-prim-008.example:
```js
const range = {
  from: 1, to: 3,
  [Symbol.iterator]() {            // well-known symbol hook
    let n = this.from, last = this.to;
    return { next: () => ({ value: n, done: n++ > last }) };
  },
};
console.log([...range]); // [1, 2, 3] — for...of/spread now work

const id = Symbol('id');
const user = { name: 'Ada', [id]: 42 };
console.log(Object.keys(user));                  // ['name'] — symbol key hidden
console.log(Object.getOwnPropertySymbols(user)); // [Symbol(id)]
```

types-nonprim-003.example:
```js
function greet() {}
console.log(typeof greet);          // 'function'
console.log(greet instanceof Object); // true — functions ARE objects

greet.callCount = 0;                 // can hold properties like any object
greet.callCount++;
console.log(greet.callCount);        // 1

const maybe = greet;
if (typeof maybe === 'function') maybe(); // idiomatic callable check
```

types-nonprim-004.example:
```js
function mutate(o) { o.x = 1; }       // mutates the shared object
function reassign(o) { o = { x: 99 }; } // rebinds local copy only

const obj = {};
mutate(obj);
console.log(obj.x); // 1 — mutation is visible

reassign(obj);
console.log(obj.x); // 1 — reassignment is NOT visible
```

types-nonprim-005.example:
```js
const o = { a: 1 };
o.a = 2;            // allowed — const freezes the binding, not the object
console.log(o.a);   // 2
// o = {};          // THIS would throw: Assignment to constant variable

const frozen = Object.freeze({ a: 1 });
frozen.a = 99;      // silently ignored (TypeError in strict mode)
console.log(frozen.a); // 1 — contents now immutable (shallowly)
```

types-nonprim-006.example:
```js
const a = { x: { y: 1 } };
const b = { ...a };     // shallow: b.x is the SAME object as a.x
b.x.y = 2;
console.log(a.x.y);     // 2 — shared nested reference

const c = structuredClone(a); // deep copy — fully independent
c.x.y = 99;
console.log(a.x.y);     // 2 — unaffected
```

types-nonprim-007.example:
```js
const obj = { fn: () => 1, u: undefined, when: new Date(), n: 5 };
const copy = JSON.parse(JSON.stringify(obj));
console.log(copy); // { when: '2026-...T...Z' (string!), n: 5 } — fn & u dropped

const safe = structuredClone({ when: new Date(), set: new Set([1, 2]) });
console.log(safe.when instanceof Date, safe.set instanceof Set); // true true
```

types-cmp-001.example:
```js
// primitives: value semantics
let x = 5, y = x; y = 9;
console.log(x, x === 5); // 5 true — independent copy

// objects: reference semantics
const a = { n: 1 }, b = a; b.n = 2;
console.log(a.n);        // 2 — same object
console.log({ n: 1 } === { n: 1 }); // false — different objects
console.log('hi' === 'hi');         // true  — equal primitives
```

types-mcq-001.example:
```js
const values = ['s', null, [1, 2], Symbol('x')];
for (const v of values) {
  // arrays report 'object'; the rest are primitives (null too, despite the bug)
  console.log(typeof v, Array.isArray(v));
}
// 'string' false | 'object' false | 'object' true | 'symbol' false
console.log(Array.isArray([1, 2])); // true — arrays are objects, not a primitive
```

types-mcq-002.example:
```js
console.log(typeof null);      // 'object' — the famous bug
console.log(typeof undefined); // 'undefined'

// reliable null check:
const x = null;
console.log(x === null);       // true
// safe object guard must exclude null:
console.log(typeof x === 'object' && x !== null); // false
```

types-mcq-003.example:
```js
const arr = [1, 2];
console.log(typeof arr === 'array'); // false — typeof says 'object'
console.log(arr instanceof Array);   // true here, unreliable cross-realm
console.log(Array.isArray(arr));     // true — the robust check

// constructor check is brittle:
const weird = []; weird.constructor = Object;
console.log(weird.constructor === Array); // false (broken) — but isArray still works:
console.log(Array.isArray(weird));        // true
```
